  VALUES 
    (701::BIGINT, 'Es un profe excelente hace el curso muy llevadero y de verdad se aprende con el'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '3e6452f4a098532a39d7a7c606f89b6f35e29222b24e90d11a57b9fe540d83fa'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'De los mejores profes de CE. Es curso no se lo va a regalar, pero busca ayudar a los estudiantes de uno u otra forma'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'a445acc6cd899ceb5c4563ec9efaae477979bd2eb4f2ca4607975ef2b9bc9eff'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Un profesor espectacular, tanto en datos 2 como en datos 1, tuve el privilegio de llevar esas dos progras con él, es un profe que sabe lo que dice y tras de que sabe que está explicando es increíble como lo explica, también dudas con temas, con algun proyecto y código el mae siempre esta dispuesto'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'a80578e84c026843d6d1ee3cd05264b99a7bd2d343db9ace7210c4eee4f2ec18'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'Es uno de los mejores profesores que tiene Computadores, se aprende mucho con él ya que se lleva bastante tiempo trabajando en la industria. Si puede llévelo con él, no se va a arrepentir'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, '397571466cffc4d5d3d9b65b14765c3bc8e5ff3ad829d264bbd5765d1576d483'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Es el mejor profesor para datos, no tenga dudas de matricular con el, los proyectos son rudos pero el siempre esta dispuesto a ayudar al estudiante. El GOAT'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '19c6ec9325fdd400dc1cb480b7d9c6f94e15d92c91e2c32c70c1bb50dce2f4ad'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'Estoy seguro que nunca voy a volver a tener un profesor de la calidad de Isaac, él es sin duda el mejor profe de ce y también hace el café más rico de Cartago. Hay algo que no haga bien?'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '44c4a4242f1df64f2b1f55a77888bdf62700369739a8f82af8e3a14cf0645ec6'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Isaac se ha coronado como el mejor profe de la carrera. Que nivel como persona y como profesor. Uno nunca se aburre con él. Explica genial la materia, te enseña ejemplos reales, despierta interés por la carrera y siempre disponible para atender dudas. Va a pasar y a aprender bastante con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'c5fc102176405782528b97c6cfeefa31d64eb489d457df1bd740af8a265dc49d'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Cada clase valió la pena. Todas las charlas que nos buscó fueron excelentes. Los proyectos fueron rudos pero se aprendió montones. Como recomendación: vaya al día con los proyectos porque abre tiempo de dudas después de clases que ayudan montones.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4d27c1dcca51cabf95ea636ee398b76f5a2a8619911c9f8bb2af2ce6a9a2bff3'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'fc89a49bc6bbe7f1a55d977efcc03e1aa67a9d3c63677115454e8118b32351f4'::TEXT, ARRAY[2993]::BIGINT[]),
    (701::BIGINT, 'Las clases eran muy interactivas, siempre busca que los estudiantes se involucren con la materia y envía documentos complementarios de mucha utilidad. Los talleres, laboratorios e investigaciones son de temas sumamente interesante para nuestra formación, así como cada una de las charlas impartidas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '403d8dfc6dc5e8afdd3d26f7aa7390fa85f1c1ece2373bb3054fc33aae4b1ad3'::TEXT, ARRAY[2993]::BIGINT[]),
    (701::BIGINT, 'Cada clase valió la pena. Todas las charlas que nos buscó fueron excelentes. Los proyectos fueron rudos pero se aprendió montones. Como recomendación: vaya al día con los proyectos porque abre tiempo de dudas después de clases que ayudan montones.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '0f9771e5234fe315e534e4d770ccdb2be9cc223622bb2a9256103f99d60ad607'::TEXT, ARRAY[2993]::BIGINT[]),
    (701::BIGINT, 'Muy buen profe, se puede aprender muchísimo de él si se tiene la disposición. Si tiene la posibilidad no duda en matricular con él.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '84911ed3a34a68ec74cdcae19074411210c8d8114894f27a053b98ac13eb7da7'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'Excelente profesor, le interesa que el estudiante aprenda, los proyectos y laboratorios son muy interesantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, '6a2276200dee3b5f8c9a0ee07346052df17f0449a8222ebb8a0363435a2fd73d'::TEXT, ARRAY[2993]::BIGINT[]),
    (701::BIGINT, 'Es un muy buen profesor'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2021-07-05T00:00:00+00:00'::TIMESTAMPTZ, '88fd41e0d04d88757e786dcc3fb5131e725f6cd21bd93b35ee105dac00fcb322'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'Simplemente no lo piensen, excelente profesor...'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ad7f97ee2b837fb415c893586a653d483f4120e84ff72374986d8769b8256696'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'b4da54ecb0efc02985d0b9a4c7536841fc75df30db9514e3ffadb4381f8da0da'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Muy buen profesor, las clases son muy amenas y de los proyectos se aprende mucho. Siempre dispuesto a ayudar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'ad4242c1f0db49af4681525f0140b681be778bfb4fa49067910951f940200768'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Es joven, bastante amigable. Enseña bien la materia y está disponible 24/7 para aclarar dudas. Le gusta lo que hace y tiene experiencia en transnacionales.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2021-02-25T00:00:00+00:00'::TIMESTAMPTZ, '79135b30a0c79b35e27e7608e82f75d59851582c429d17f9d0603eaadfe8d5f3'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Es un profe excelente, le pone esfuerzo a las clases y se preocupa por el aprendizaje de uno. También hace chistes divertidos y da mucha retroalimentación para la parte laboral.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '9dba55755cdc4954b03b8a120b111b975fc8475ca12eb6083c84d1770a17de1a'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'Es un MUY buen profe, tiene mucha paciencia, y atiende consultas sin problemas. Además responde preguntas laborales que tenga. Califica muy justo y le da importancia a ligar la clase con la vida real. Aprendí muchísimo 100% recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '99f257ce9258a8ac9d63b04b4e86e32c63a680cbe45fc28d772fbd088fb68a4e'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Explica muy bien y repite las veces que sea necesario. Califica bastante justo y toma en cuenta el esfuerzo. Habla mucho sobre el trabajo e intenta que las progras se relacionen con cosas de la vida real, lo que agrega mucho valor a las clases. También es súper pura vida y hace comentarios graciosos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '0694ea6b6ff4bea93b440bb97b0e3f53eba523d8e194e77a291a6fafac85c9a8'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'De los mejores profesores que he tenido, el curso es muy teórico y la materia la explica de forma muy clara, pero si es necesario repite las veces que sean. También le da un valor agregado al curso con muchos talleres y consejos útiles sobre buenas prácticas de programación y herramientas útiles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '63d9f434e946fcf0f302f1f588979b7bc7b31558df727479885fa21bbfc8c3d0'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'El curso por sí solo es bastante pesado, así que se ocupa tener un profe como él, ya que ayuda a sus estudiantes en cualquier momento. Me tocó llevarlo virtual con él y su calidad no bajó a pesar del cambio. Si tiene el chance matricule con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, '500204be9135378bbdac13b48009a14a7580b5d17bd1b832c9c9aebd2e19ec65'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'gg, buen profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '0245e51bd5d0c970623e1d60feb85f16b2dd9227fa2ccee7f60c0ff1cb77a54e'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'De lo mejor que hay en Computadores, explica todo lo que usted le pregunte y es demasiado pura vida como persona'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, 'f7b385fd0983313cc0673d99e9366373b2675da2746965efecb600cf47cdbb52'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, '10/10 Excelente Servicio'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b1199d740bfdea811429b1cfd01e849a21f90f1385507a527a1c59ad155562e0'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Profesor siempre atento a las dudas de los estudiantes y da clases por gusto y no por dinero. Tiene un trabajo mucho mejor remunerado que dar clases en el Tec, usualmente siempre da clases den la tarde/noche. Explica muy claro y como dije se preocupa porque la gente entienda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-05-18T00:00:00+00:00'::TIMESTAMPTZ, 'db4d8d751777aecaa8a94585130cdded7249b8d6cb38b29bcbaf4460bfcb914b'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '6187418588f82e322908b8b6c105ec3148bc9432329aa786b8e5be4353fb99a8'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'No hace muchos quices, tareas normal. Es vaguito pero súper buen profe, y ofrece ayuda para las progras siempre (mientras no falten dos días para entrega). Lo prepara a uno para bretear ya afuera.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a5c35206957386d83f3ebd5c11bd20b20430c6a5c76c3b02d1bfd456b4e3aa3f'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'Excelente profesor, recomendadísimo. El mae es un toque desordenado e impuntual para entregar calificaciones de vez en cuando, pero esto lo compensa con las clases que da. Además de que se da a entender la materia, habla mucho acerca de la vida profesional, lo cual sirve muchísimo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-21T00:00:00+00:00'::TIMESTAMPTZ, 'e6766259ba46a68a20a8c2229be1ec5e6426a1e6e27169e6104749dd6c32e6eb'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Muy buen profe. Explica claro y hace la clase muy interesante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-28T00:00:00+00:00'::TIMESTAMPTZ, '9c40c79ef5e9d06d726c4fbb6468feb844bc6392e5b95d217f8fa455433507b6'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Excelente Profesor, confiado en su trabajo es feliz en lo que hace. Inspira en los estudiantes deseo por el mundo del software. Cuanto a las progras, no califica tan duro ayuda si usted le pone. Tarda en revisar los entregables.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'cc831be0efe82258f62bab4ae321c0b2a918d0a85512c838a11d622ec9066f72'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Excelente profe, da generalmente mas tiempo para las progras, ayuda en las revision y no califica a matar, sino a lo justo a su trabajo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'f4c48c5608c35ceca64e2460c4e251293fa37e47dc46644d5906733d49e38b28'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'El profe es super bueno, a mi me costo el curso por eso recomiendo siempre llegar a hacer las cosas que el profe explica en clases. Ayuda con los tiempos de las progras y es super accesible, un profe que se interesa montones por el bienestar del estudiante. hola profe :D'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2018-06-28T00:00:00+00:00'::TIMESTAMPTZ, '7f3b9d1c5fbbf52e9c6f1b56fb1aae832a4b7002e3cd27527ef7206a9cafecae'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Buen profe, ayuda con el tiempo de las progras y califica justo en las progras e incluso puede llegar a ayudar en algunas durante la revisión. Totalmente recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'f2cabfd80c4d0a33797041845ce483652f54818c505f2d70c9d378d2134bef89'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Es un excelente profe, hace las clases muy entretenidas (literalmente uno se ríe muchas veces), y se preocupa por que uno aprenda. Solo dos cosas: 1 - las respuestas a consultas por mensajes son muy cortas y a veces no contesta. 2 - En revisión de progra es demasiado insoportable :''v'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '2f9f0747ce052e4a30146bcfeca869940798316e7395a9d31c36962b1dc5fffd'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Excelente profe, explica con claridad y se devuelve a explicar si uno no entiende, ayuda bastante, califica suave, es muy accesible, las clases se vuelven entretenidas ya que vacila mucho, se aprende bastante si se pone de su parte también. Hola profe! :P'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5ed35aa459f0941e1e834bc31dd3c87601db62173c75a8c865b55f5c87fef53a'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Excelente profe, no pone presentaciones y las clases no se hacen aburridas, ponga de su parte, y en el curso le va excelente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'bad7213a55597fd61257adc544f7f722b37690d90d197e7406001362fd369e68'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'El mejor profe para datos, ayuda bastante si usted le pone y le consulta cualquier duda. Un saludo al profe que yo se que esta viendo esto'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'fa158ca62d1cf53d3d949f851e91a876dc46cf2d13339d033d731a60bfcd936c'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'El mejor, simplemente no se siente que uno está en clases.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '7fc7f5d9d6bfa8c6e26a60414d81ca6d0048dc1b2ed5a1ca23e573a8719e6d24'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'De lo mejor que tiene CE. Super cómico, da anécdotas de la vida laboral, explica excelente, si no le entiende ya no tiene con quién...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2018-05-23T00:00:00+00:00'::TIMESTAMPTZ, '8ce8083460325c7d123afdd563d988cab1dc69d60888e1d71e64a77e226457ee'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Es un crack! tiene todas para ser orgulloso y mantiene su humildad, le da consejos a todos para cuando trabajen en esa area y hace que uno entienda que todo depende del interes del estudiante, califica justo, explica super claro con ejemplos creativos. No dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'ab7ca51d9de52808517574080af1bab6abfb7c48d06eded347213629d53a2da4'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'El mejor profe que ud va a tener en su vida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '2fe68ac12634617db979d2a1fb9a081b8a76d06c799363e9be87dbae0a233bdf'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Es super tuanis con todos, ayuda para la entrega de proyectos y revisa normal, las tareas, quices y proyectos no son muy dificiles'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'a7c7bfcbc7b14eb1b1d6193ef5f31a3b1140cfddcfefdd9d6d943729cd386cef'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '11b690cc5fc09e3e9daccb6b54dfe258841083141b1573652c67ed66364cd4a7'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'd393b888dac6436b258b94d5a8089ee9d15244c2a95ab714c5c7ea56474f68d1'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Es un profesor muy justo y comprensivo a la hora de calificar y con respecto a entrega de trabajos. Super tuanis con los alumnos. El curso en sí no es fácil pero el profe está dispuesto a explicar varias veces y deja trabajos que pueden ser útiles para que los estudiantes añadan al currículum'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4f9df90ca8d218f597abe44c0155454e8c8de6a5fca277672ff1e620c50551e6'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'De los mejores profesionales de computadores, definitivamente el mejor para Datos, no ha llevado cursos de pedagogía (pero eso es bueno, que no le hacen falta ni un poco), hace las clases entretenidas y divertidas, volvería a matricular con él sin dudarlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'bf592c7670e41bddb9844bb1860752a3c88deffc2b1c33e59f9ece89a8118667'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (701::BIGINT, 'Si tiene la oportunidad, no dude en llevar con él. Las clases son muy entretenidas, ligeras y en general se tiene un buen ambiente. Él siempre está atento para que uno de lo mejor de si mismo cuando sea un profesional y da consejos increíblemente buenos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'fe27f6833a9506b1730b44d3d1f495215404277cad3862e35fd4ac2ab273c35c'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'GG EZPZ LEMON SQUEZZY x2'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, '5de71e1a06727ce4752b4f8ef5046b3fd6bc4322e5b6c388460defbb4a03f55d'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Excelente profe, muy justo y en las clases normalmente hace referencias a la teoría aplicada en el ámbito laboral. No ha llevado cursos de pedagogía pero no los necesita. (El probablemente lea esto :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-23T00:00:00+00:00'::TIMESTAMPTZ, '66e400f310ebee8f01ed75c50607272677b8495b3f1599cfe91a7756dbfa7afc'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Un excelente profesor que de verdad lo quiere preparar a uno para la vida laboral. Y las clases son bastante entretenidas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'ee955f7d06e61bdb0801c91a68221c7be6b36b3f449ac241bc5bd39c15a7c479'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Un profesor que le importa el producto final en lugar de los objetivos cumplidos en los proyectos programados; a pesar de no haber llevado ningún curso de pedagogía es un muy buen profesor.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, '15285c41230b36a61bac4c93d1c0eb5f8ba147ac0bc4d1adba6e864554d83fba'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Buen profe, se lleva de maravilla con sus estudiantes. Le gusta que los proyectos esten integrados, y funcionales, explica bien, y trabaja con las herramientas utilizadas en la calle'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-05T00:00:00+00:00'::TIMESTAMPTZ, '243725032f21290efd2fbeeaca3a489df08c7fd51c9f08bc6e86cd23057493b4'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'GG EZPZ LEMON SQUEZZY'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, '659d0f0d26e0521c5acc162e72cd2bb8358530046b8f104ab9aebdcd5b391c7e'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Un muy buen profe. Le importa mucho que los estudiantes asistan a sus clases y también cubre temas que el considera importantes que se usan en la actualidad. Lo mejor es que no se dependa del último examen.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2016-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'd13ee257ebae2d1c158016faabcbf255832c3554540ef001c77fb2eddfea9fb0'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'El curso es duro, entonces hay que llegar al examen casi que pasado el curso!! Explica excelente la materia y da muy buenos consejos en relacion con la carrera'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '9cf3230ba2cec1697ec6b2ac8136adb2a076b3c964f81639b6b01a9b7a3f312a'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'La clase se hace entretenida, ayuda mucho indicandole a uno cuando algo se debe aprender xq se usa a diario o incluso lo que siempre preguntan en las entrevistas. Algunos temas no los explica muy a profundo (xq el dice que no se usan mucho). Si se le demuestra que se esfuerza califica suave.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'eeb859457b96d9778a638e2545af292d43f9268ace66ff2784e165f30c2ad5d1'::TEXT, ARRAY[2965]::BIGINT[]),
    (701::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases excelentes']::TEXT[], '2016-03-22T00:00:00+00:00'::TIMESTAMPTZ, 'd50a3e144b90a1a413bfe38bfc179960f1369097ddb8287090383f587a9cfa4a'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Profesor con mucho conocimiento que sabe transmitir perfectamente al estudiante, sabe mucho de la materia pero aun mas importante sabe mucho sobre la vida laboral y da constantes anécdotas de su trabajo. Ayuda mucho, no regala puntos pero esta dispuesto a explicar las veces que sea.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador']::TEXT[], '2016-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'c23b00d2fc89bde3ab5d3824f00d016c73a64d97a773bb27008395416b71122f'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Solo lee las presentaciones, hay temas del curso que no domina. Las progras las califica suave y se fija en el esfuerzo del estudiante.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-06T00:00:00+00:00'::TIMESTAMPTZ, 'd460b4904b5913c6682030613546f3de32f7e73e348adcb7a826add0c658d63a'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Muy buen profe, explica lo que debe y de buena forma. A la hora de revisar, si la progra funciona no lo jode mucho revisando, lo unico que pide es que todo este integrado. Recomendado!!'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'd81382d5211f65f72284e414ad287c0bf633f3ecd707d7dba090270f10e81676'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Es un excelente profe y explica super bien, aunque un curso como datos no se pasa yendo a clases. Es bastante exigente en las progras sin embargo si uno desde el principio le pone y saca buena nota en el resto no lo jode tanto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-23T00:00:00+00:00'::TIMESTAMPTZ, '38cb15596cc93e73b98a9092e1e715521b92b93a2ab4347516456bce9419336d'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'd87d2a5dd838ad09321204977ca97b149ea83de6c07cba365a8e9a93a6a821b2'::TEXT, ARRAY[2962]::BIGINT[]),
    (701::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'ded58615b2820ca86e9c8626f3a648fc6b8c4f2e998a4feb1d34e83593b31463'::TEXT, ARRAY[2970]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
